mapper.sql:
 FROM (SELECT crd02_data.*
            , COALESCE((SELECT 'O'
                          FROM biz01_promo
                         WHERE biz01_std_ym = #{dataYm}
                           AND biz01_company_id = #{companyId}
                           AND crd02_data_id = biz01_card_data_id), '') AS crd02_confirm_yn
         FROM crd02_data
        WHERE COALESCE(crd02_card_no, '') || COALESCE(crd02_franchise_nm, '') || COALESCE(crd02_biz_license_no, '')
              || COALESCE(crd02_representative_nm, '') LIKE #{searchText}
          AND crd02_data_ym LIKE #{dataYm}
          AND crd02_data_bank_cd LIKE #{dataBankCode}
          AND crd02_company_id = #{companyId}) t
WHERE crd02_confirm_yn LIKE #{confirmCode}
  AND crd02_state_nm NOT LIKE #{stateCode}

mapper.select:
SELECT SUM(crd02_approval_amount) AS total_approval_amount
     , SUM(crd02_surtax)          AS total_surtax
  FROM crd02_data
 WHERE COALESCE(crd02_card_no, '') || COALESCE(crd02_franchise_nm, '') || COALESCE(crd02_biz_license_no, '')
       || COALESCE(crd02_representative_nm, '') LIKE #{searchText}
   AND crd02_data_ym LIKE #{dataYm}
   AND crd02_data_bank_cd LIKE #{dataBankCode}
   AND crd02_company_id = #{companyId}
   AND COALESCE((SELECT 'O'
                   FROM biz01_promo
                  WHERE biz01_std_ym = #{dataYm}
                    AND biz01_company_id = #{companyId}
                    AND crd02_data_id = biz01_card_data_id), '') LIKE #{confirmCode}
   AND crd02_state_nm NOT LIKE #{stateCode}

SELECT 
     , COALESCE((SELECT 'O' FROM biz01_promo WHERE biz01_company_id = crd02_company_id AND crd02_data_id = biz01_card_data_id LIMIT 1), '') AS confirm_yn
  FROM crd02_data
 WHERE crd02_company_id = #{companyId}
   AND crd02_data_id IN #{id}
 ORDER BY crd02_approval_dt, crd02_approval_time, crd02_franchise_nm

SELECT 
     , COALESCE((SELECT 'O' FROM biz01_promo WHERE biz01_company_id = crd02_company_id AND crd02_data_id = biz01_card_data_id LIMIT 1), '') AS confirm_yn
  FROM crd02_data
 WHERE crd02_data_id = #{dataId}
   AND crd02_company_id = #{companyId}

WITH approval_number AS (
    SELECT 'syscode' || LPAD((ROW_NUMBER() OVER (ORDER BY crd02_approval_no) + 1)::text, 3, '0') AS syscode_value
      FROM crd02_data
     WHERE crd02_data_ym = #{dataYm}
       AND crd02_company_id = #{companyId}
       AND crd02_approval_no LIKE '%syscode%'
)
SELECT COALESCE(MAX(syscode_value), 'syscode001') AS crd02_approval_no
  FROM approval_number

mapper.insert:
INSERT INTO crd02_data
     ( crd02_data_id, crd02_company_id, crd02_data_ym, crd02_data_bank_cd, crd02_approval_dt, crd02_approval_time
     , crd02_part_cd, crd02_part_nm, crd02_card_no, crd02_card_nm, crd02_franchise_nm, crd02_sector_nm
     , crd02_payment_method, crd02_monthly_payments, crd02_approval_amount, crd02_surtax
     , crd02_approval_classification, crd02_approval_method, crd02_approval_no, crd02_state_nm, crd02_tax_ty
     , crd02_merchant_status, crd02_merchant_no, crd02_biz_license_no, crd02_representative_nm
     , crd02_merchant_addr, crd02_merchant_phone )
VALUES
     ( #{dataId}, #{companyId}, #{req.dataYm}, #{req.dataBankCode}, #{req.approvalDt}, #{req.approvalTime}
     , #{req.partCode}, #{req.partName}, #{req.cardNo}, #{req.cardName}, #{req.franchiseName}, #{req.sectorName}
     , #{req.paymentMethod}, #{req.monthlyPayments}, #{req.approvalAmount}, #{req.surtax}
     , #{req.approvalClassification}, #{req.approvalMethod}, #{req.approvalNo}, #{req.stateName}, #{req.taxTy}
     , #{req.merchantStatus}, #{req.merchantNo}, #{req.bizLicenseNo}, #{req.representativeName}
     , #{req.merchantAddr}, #{req.merchantPhone} )

