UPDATE biz01_promo
   SET biz01_company_id = #{companyId}
     , biz01_provide_date = #{row.approvalDt}
     , biz01_provide_rcv_type = '1'
     , biz01_settle_type = '1'
     , biz01_card_data_id = #{row.dataId}
     , biz01_card_id = #{cardId}
     , biz01_provide_amt = #{amount}
     , biz01_tax = #{tax}
     , biz01_std_ym = #{row.dataYm}
     , biz01_tax_type = #{taxType}
 WHERE biz01_promo_id = #{promoId}

mapper.select:
SELECT biz01_promo_id    AS promo_id
     , biz01_provide_amt AS provide_amt
     , biz01_tax         AS tax
  FROM biz01_promo
 WHERE biz01_company_id = #{companyId}
   AND biz01_std_ym = #{dataYm}
   AND biz01_card_data_id IN (SELECT crd02_data_id
                                FROM crd02_data
                               WHERE crd02_approval_no = #{approvalNo}
                                 AND crd02_company_id = #{companyId}
                                 AND crd02_state_nm LIKE #{stateName})
 LIMIT 1

